proposals.minimal_replacement_snippet_not_applied:
time-label := Text {
    x: Theme.margin; y: 0px;
    width: State.large-screen && State.incognito ? self.preferred-width : 90px;
    height: parent.height; text: State.time; font-family: Theme.numbers;
    font-size: root.status-font; font-weight: 600; color: root.foreground;
    vertical-alignment: TextVerticalAlignment.center;
}
if State.incognito: Text {
    x: State.large-screen ? time-label.x + time-label.width + root.status-gap : root.notice-inset;
    y: 0px;
    width: State.large-screen ? max(0px, wifi-indicator.x - root.status-gap - self.x) : max(0px, root.width - root.notice-inset * 2);
    height: root.height;
    text: State.large-screen ? Strings.scribe-incognito-status : Strings.incognito-status;
    font-family: Theme.sans; font-size: State.large-screen ? 14px : 12px;
    font-weight: 700; letter-spacing: State.large-screen ? 3px : 2px;
    color: Theme.paper; horizontal-alignment: TextHorizontalAlignment.center;
    vertical-alignment: TextVerticalAlignment.center; overflow: elide;
}

property <bool> available: !root.completed && !root.active && !root.queued && root.entry.download-state != "failed";

if !root.active && !root.available: Icon {
    x: (parent.width - self.width) / 2; y: (parent.height - self.height) / 2;
    width: State.large-screen ? 18px : 15px; height: self.width;
    kind: root.completed ? "check" : root.queued ? "history" : root.entry.download-state == "failed" ? "warning" : "download";
    inverted: root.completed != touch.pressed;
}
if root.available: Path {
    x: (parent.width - self.width) / 2; y: (parent.height - self.height) / 2;
    width: State.large-screen ? 18px : 15px; height: self.width;
    viewbox-width: 24; viewbox-height: 24;
    fill: transparent; stroke: touch.pressed ? Theme.paper : Theme.ink;
    stroke-width: State.large-screen ? 2.6px : 2.8px;
    stroke-line-cap: round; stroke-line-join: round;
    accessible-role: none;
    commands: "M12 5v12M7 12l5 5 5-5";
}
